selector_to_html = {"a[href=\"#wait-strategies\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Wait Strategies<a class=\"headerlink\" href=\"#wait-strategies\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#complex-workflows\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Complex Workflows<a class=\"headerlink\" href=\"#complex-workflows\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#error-handling\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Error Handling<a class=\"headerlink\" href=\"#error-handling\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#page-information\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Page Information<a class=\"headerlink\" href=\"#page-information\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#permissions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Permissions<a class=\"headerlink\" href=\"#permissions\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#geolocation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Geolocation<a class=\"headerlink\" href=\"#geolocation\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#media-emulation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Media Emulation<a class=\"headerlink\" href=\"#media-emulation\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#syntax\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Syntax<a class=\"headerlink\" href=\"#syntax\" title=\"Link to this heading\">#</a></h2><p>You can also load the function from a file:</p>", "a[href=\"#running-custom-playwright-code\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Running Custom Playwright Code<a class=\"headerlink\" href=\"#running-custom-playwright-code\" title=\"Link to this heading\">#</a></h1><p>Use <code class=\"docutils literal notranslate\"><span class=\"pre\">run-code</span></code> to execute arbitrary Playwright code for advanced scenarios not covered by CLI commands.</p>", "a[href=\"#file-downloads\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">File Downloads<a class=\"headerlink\" href=\"#file-downloads\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#frames-and-iframes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Frames and Iframes<a class=\"headerlink\" href=\"#frames-and-iframes\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#clipboard\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Clipboard<a class=\"headerlink\" href=\"#clipboard\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#javascript-execution\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">JavaScript Execution<a class=\"headerlink\" href=\"#javascript-execution\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
